5	const isSphinx = (card: Card): boolean => card.monster === "sphinx";
6	
7	const TYPES_SCORED_AT_FACE_VALUE = 3;
8	const POINTS_PER_SPHINX = 1;
9	
10	const distinctNonSphinxTypes = (army: Card[]): number =>
11	  new Set(army.filter((card) => !isSphinx(card)).map((card) => card.monster))
12	    .size;
13	
14	const pointsForOtherTypes = (typeCount: number): number =>
15	  typeCount > TYPES_SCORED_AT_FACE_VALUE
16	    ? 2 * (typeCount - TYPES_SCORED_AT_FACE_VALUE)
17	    : 1;
18	
19	const scoreOneSphinx = (otherTypes: number): number =>
20	  POINTS_PER_SPHINX + pointsForOtherTypes(otherTypes);
21	
22	export const scoreArmy = (army: Card[]): number => {
23	  const sphinxCount = army.filter(isSphinx).length;
24	  return sphinxCount * scoreOneSphinx(distinctNonSphinxTypes(army));
25	};
